1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { z } from "zod";
5	import { db } from "./db";
6	import { requireUser, assertNotImpersonating } from "./auth";
7	import { InsufficientBalanceError } from "./wallet";
8	import { resizeQuote, applyResize, ResizeError } from "./resize";
9	import { createResizeCheckout } from "./stripe";
10	import { walletSplit } from "./wallet-split";
11	import { emailVerificationError } from "./email-verification";
12	
13	async function ownedServer(serverId: string) {
14	  const user = await requireUser();
15	  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
16	  if (!server) throw new Error("Not found");
17	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
18	  return { user, server };
19	}
20	
21	async function queueJob(
22	  serverId: string,
23	  type:
24	    | "SNAPSHOT_CREATE"
25	    | "SNAPSHOT_DELETE"
26	    | "SNAPSHOT_ROLLBACK"
27	    | "BACKUP_CREATE"
28	    | "RESIZE"
29	    | "PASSWORD_RESET",
30	  payload?: Record<string, unknown>
31	): Promise<{ error?: string }> {
32	  const pending = await db.job.count({
33	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
34	  });
35	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
36	  await db.job.create({ data: { type, serverId, payload: payload as any } });
37	  return {};
38	}
39	
40	// ---------- Snapshots ----------
41	
42	/**
43	 * The ONE snapshot-name normalisation, applied identically on every path.
44	 *
45	 * `worker/index.ts` snapshotOp re-applies exactly this (`[^a-zA-Z0-9_]` stripped,
46	 * 40 chars) and throws "snapshot: invalid name" on an empty result — so a name
47	 * this module accepts but the worker rejects is a job that reports QUEUED to the
48	 * customer and then dies in the worker with a message they never see. Delete and
49	 * rollback used to pass the raw argument straight through: a TypeScript parameter
50	 * type is not validation, and these are reachable with any string at all.
51	 */
52	function cleanSnapshotName(name: unknown): string {
53	  return String(name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
54	}
55	
56	const SNAPSHOT_NAME_ERROR =
57	  "Snapshot name must be 2–40 characters of letters, digits or underscores. " +
58	  "Pick the snapshot from the list on the server page rather than typing its name.";
59	
60	export async function createSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
61	  const { user, server } = await ownedServer(serverId);
62	  const clean = cleanSnapshotName(name);
63	  if (clean.length < 2) return { error: "Snapshot name: letters, digits, underscores (min 2)." };
64	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
65	    return { error: "Server must be running or stopped." };
66	  }
67	  const res = await queueJob(serverId, "SNAPSHOT_CREATE", { name: clean });
68	  if (!res.error) {
69	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_create", detail: `${serverId} ${clean}` } });
70	    revalidatePath(`/dashboard/servers/${serverId}`);
71	  }
72	  return res;
73	}
74	
75	export async function deleteSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
76	  const { user } = await ownedServer(serverId);
77	  const clean = cleanSnapshotName(name);
78	  if (clean.length < 2) return { error: SNAPSHOT_NAME_ERROR };
79	  const res = await queueJob(serverId, "SNAPSHOT_DELETE", { name: clean });
80	  if (!res.error) {
81	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_delete", detail: `${serverId} ${clean}` } });
82	    revalidatePath(`/dashboard/servers/${serverId}`);
83	  }
84	  return res;
85	}
86	
87	export async function rollbackSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
88	  const { user, server } = await ownedServer(serverId);
89	  const clean = cleanSnapshotName(name);
90	  if (clean.length < 2) return { error: SNAPSHOT_NAME_ERROR };
91	  // A rollback rewinds the VM's disk. The worker can only do that against a real
92	  // VM in a steady state — the same precondition createSnapshot already enforced.
93	  // Without it we accepted the request, said nothing, and let the job fail in the
94	  // worker while the customer believed their server was being restored.
95	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
96	    return { error: "Server must be running or stopped to roll back to a snapshot." };
97	  }
98	  const res = await queueJob(serverId, "SNAPSHOT_ROLLBACK", { name: clean });
99	  if (!res.error) {
100	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_rollback", detail: `${serverId} ${clean}` } });
101	    revalidatePath(`/dashboard/servers/${serverId}`);
102	  }
103	  return res;
104	}
105	
106	// ---------- Backups ----------
107	
108	export async function createBackup(serverId: string): Promise<{ error?: string }> {
109	  const { user, server } = await ownedServer(serverId);
110	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
111	    return { error: "Server must be running or stopped." };
112	  }
113	  const res = await queueJob(serverId, "BACKUP_CREATE");
114	  if (!res.error) {
115	    await db.auditLog.create({ data: { userId: user.id, action: "server.backup_create", detail: serverId } });
116	    revalidatePath(`/dashboard/servers/${serverId}`);
117	  }
118	  return res;
119	}
120	
121	export type BackupJobStatus = {
122	  id: string;
123	  type: "BACKUP_CREATE" | "BACKUP_RESTORE";
124	  status: "QUEUED" | "RUNNING" | "DONE" | "FAILED";
125	  progress: number;
126	  step: string | null;
127	  error: string | null;
128	  createdAt: string;
129	};
130	
131	/**
132	 * Return the most recent backup/restore job for a server so the UI can render a
133	 * live progress bar. Ownership-checked. Returns null if the server has never had
134	 * a backup/restore job. The client decides when to show the bar (in-flight) vs.
135	 * the completion/failure note.
136	 */
137	export async function getBackupJob(serverId: string): Promise<BackupJobStatus | null> {
138	  const { server } = await ownedServer(serverId);
139	  const job = await db.job.findFirst({
140	    where: { serverId: server.id, type: { in: ["BACKUP_CREATE", "BACKUP_RESTORE"] } },
141	    orderBy: { createdAt: "desc" },
142	    select: { id: true, type: true, status: true, progress: true, step: true, error: true, createdAt: true },
143	  });
144	  if (!job) return null;
145	  return {
146	    id: job.id,
147	    type: job.type as BackupJobStatus["type"],
148	    status: job.status as BackupJobStatus["status"],
149	    progress: job.progress,
150	    step: job.step,
151	    error: job.error,
152	    createdAt: job.createdAt.toISOString(),
153	  };
154	}
155	
156	// ---------- Resize ----------
157	
158	export async function resizeServer(
159	  serverId: string,
160	  planId: string,
161	  useWallet: boolean = true,
162	): Promise<{ error?: string; checkoutUrl?: string }> {
163	  // Spend path: an upgrade debits the wallet (and can open a Stripe Checkout in
164	  // the customer's name), so it carries the same impersonation guard as every
165	  // other money movement — lib/actions-disk.ts expandServerDisk, lib/actions.ts
166	  // payAndDeploy/topUp/renewNow, and the domain transfer actions.
167	  // This one was missed, which made "upgrade the plan" the one charge an admin
168	  // impersonating a customer could still put on that customer's balance.
169	  await assertNotImpersonating();
170	  const { user, server } = await ownedServer(serverId);
171	  // Purchase gate: an upgrade is a charge (wallet or card). Downgrades live in
172	  // resizeServerDown and are deliberately NOT gated — that path REFUNDS, and
173	  // stopping a customer from spending LESS would be a gate with no one to
174	  // protect. See lib/email-verification.ts.
175	  const unverified = await emailVerificationError(user);
176	  if (unverified) return { error: unverified };
177	
178	  // Validate + price the upgrade (ownership already checked above). resizeQuote
179	  // recomputes the exact prorated charge over the remaining term.
180	  let quote;
181	  try {
182	    quote = await resizeQuote(serverId, planId);
183	  } catch (e) {
184	    if (e instanceof ResizeError) return { error: e.message };
185	    throw e;
186	  }
187	  const { newPlan, prorateCents } = quote;
188	
189	  // Wallet-aware split — identical logic to the deploy flow. ResizePicker computes
190	  // the same split (lib/wallet-split.ts) so displayed === charged.
191	  const { cardCents } = walletSplit({
192	    dueCents: prorateCents,
193	    balanceCents: user.balanceCents,
194	    useWallet,
195	  });
196	
197	  // Card portion > 0 → charge ONLY the remainder on the card (not the full
198	  // proration). The confirm route credits the card amount to the wallet and then
199	  // debits the FULL proration (encoded as chargeCents), so the wallet absorbs its
200	  // share and the card the rest — wallet never touched before the card clears.
201	  if (cardCents > 0) {
202	    const url = await createResizeCheckout(user, cardCents, {
203	      serverId,
204	      planId,
205	      planName: newPlan.name,
206	      prorateCents,
207	    });
208	    if (!url) {
209	      return {
210	        error: `Upgrading costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
211	      };
212	    }
213	    return { checkoutUrl: url };
214	  }
215	
216	  // Card portion is $0 (wallet fully covers it, or the charge is $0 for free/admin
217	  // servers) → apply instantly, debiting the full proration from the wallet.
218	  try {
219	    await applyResize({ serverId, planId, actorUserId: user.id });
220	  } catch (e) {
221	    if (e instanceof ResizeError) return { error: e.message };
222	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
223	    throw e;
224	  }
225	  revalidatePath(`/dashboard/servers/${serverId}`);
226	  return {};
227	}
228	
229	// ---------- Root password reset ----------
230	
231	export async function resetRootPassword(serverId: string): Promise<{ error?: string }> {
232	  const { user, server } = await ownedServer(serverId);
233	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
234	    return { error: "Server must be running or stopped to reset its password." };
235	  }
236	  const res = await queueJob(serverId, "PASSWORD_RESET");
237	  if (!res.error) {
238	    await db.auditLog.create({
239	      data: { userId: user.id, action: "server.password_reset", detail: serverId },
240	    });
241	    revalidatePath(`/dashboard/servers/${serverId}`);
242	    revalidatePath(`/admin/servers/${serverId}`);
243	  }
244	  return res;
245	}
246	
247	// ---------- Port forwarding (firewall/networking) ----------
248	
249	import { SSH_PORT_START as PF_MIN, SSH_PORT_END as PF_MAX } from "./ipam";
250	const MAX_FORWARDS_PER_SERVER = 10;
251	
252	export async function addPortForward(prev: any, formData: FormData): Promise<{ error?: string }> {
253	  const serverId = String(formData.get("serverId") ?? "");
254	  const { user, server } = await ownedServer(serverId);
255	  const parsed = z
256	    .object({
257	      guestPort: z.coerce.number().int().min(1).max(65535),
258	      protocol: z.enum(["tcp", "udp"]),
259	    })
260	    .safeParse({ guestPort: formData.get("guestPort"), protocol: formData.get("protocol") ?? "tcp" });
261	  if (!parsed.success) return { error: "Invalid port." };
262	
263	  const count = await db.portForward.count({ where: { serverId } });
264	  if (count >= MAX_FORWARDS_PER_SERVER) return { error: `Limit of ${MAX_FORWARDS_PER_SERVER} forwards reached.` };
265	
266	  // Allocate the public port with the DB as the arbiter, not this read.
267	  //
268	  // `PortForward.publicPort` is UNIQUE (prisma/schema.prisma). Choosing a port
269	  // from a snapshot read and inserting it unguarded meant two requests that
270	  // overlapped — a double-click, or two customers adding a forward at the same
271	  // moment — both picked the same lowest free port and the loser's insert threw
272	  // a raw Prisma P2002. That exception escaped this action, so the customer got
273	  // a server-error page instead of a message, and (in production, where Next
274	  // redacts action errors) no clue what happened or that simply retrying works.
275	  //
276	  // Retry across the next few free candidates so an ordinary collision resolves
277	  // itself silently, and turn a genuine exhaustion into an honest, actionable
278	  // message rather than a crash.
279	  const used = new Set([
280	    ...(await db.portForward.findMany({ select: { publicPort: true } })).map((p) => p.publicPort),
281	    ...(await db.server.findMany({ where: { sshPort: { not: null } }, select: { sshPort: true } })).map((s) => s.sshPort!),
282	  ]);
283	  const candidates: number[] = [];
284	  for (let p = PF_MIN; p <= PF_MAX && candidates.length < 8; p++) {
285	    if (!used.has(p)) candidates.push(p);
286	  }
287	  if (candidates.length === 0) {
288	    return {
289	      error:
290	        "Every public port in the forwarding pool is in use, so we can't allocate one for this rule. " +
291	        "Delete a forward you no longer need, or contact support to have the pool widened.",
292	    };
293	  }
294	
295	  let publicPort = 0;
296	  for (const candidate of candidates) {
297	    try {
298	      await db.portForward.create({
299	        data: { serverId, publicPort: candidate, guestPort: parsed.data.guestPort, protocol: parsed.data.protocol },
300	      });
301	      publicPort = candidate;
302	      break;
303	    } catch (e: any) {
304	      // P2002 = another request took this port between our read and this insert.
305	      // Anything else is a real failure and must not be swallowed.
306	      if (e?.code !== "P2002") throw e;
307	    }
308	  }
309	  if (!publicPort) {
310	    return {
311	      error:
312	        "Another request took the public port we picked, several times in a row. " +
313	        "Nothing was created — please try adding the forward again.",
314	    };
315	  }
316	
317	  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
318	  await db.auditLog.create({
319	    data: { userId: user.id, action: "server.portforward_add", detail: `${serverId} :${publicPort}->${parsed.data.guestPort}/${parsed.data.protocol}` },
320	  });
321	  revalidatePath(`/dashboard/servers/${serverId}`);
322	  return {};
323	}
324	
325	export async function deletePortForward(serverId: string, forwardId: string) {
326	  const { user } = await ownedServer(serverId);
327	  await db.portForward.deleteMany({ where: { id: forwardId, serverId } });
328	  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
329	  await db.auditLog.create({
330	    data: { userId: user.id, action: "server.portforward_delete", detail: `${serverId} ${forwardId}` },
331	  });
332	  revalidatePath(`/dashboard/servers/${serverId}`);
333	}
