1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser, assertNotImpersonating } from "./auth";
6	// Re-exporting a const from a "use server" file is illegal (Next throws
7	// "found object"), so the choices live in a plain module.
8	import { BACKUP_INTERVAL_CHOICES } from "./backup-intervals";
9	import { prorateDowngradeCreditCents, remainingMonths } from "./proration";
10	import { annualDiscountPct } from "./annual-discount";
11	
12	/**
13	 * Server lifecycle "extras" — scheduled backups, reinstall-to-a-different-OS and
14	 * resize-down. These complement the primary flows in `lib/actions-server.ts`
15	 * (create backup, resize-up, reinstall-same-OS). Every op is ownership-checked
16	 * and respects the "one in-flight job per server" invariant.
17	 */
18	
19	async function ownedServer(serverId: string) {
20	  const user = await requireUser();
21	  const server = await db.server.findUnique({
22	    where: { id: serverId },
23	    include: { plan: true, osTemplate: true },
24	  });
25	  if (!server) throw new Error("Not found");
26	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
27	  return { user, server };
28	}
29	
30	async function hasInflightJob(serverId: string): Promise<boolean> {
31	  const pending = await db.job.count({
32	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
33	  });
34	  return pending > 0;
35	}
36	
37	// ---------- 1. Scheduled backups ----------
38	
39	/**
40	 * Enable/disable recurring backups and set the cadence. When enabling we do NOT
41	 * touch `lastAutoBackup` — a null/stale value simply lets the sweep run the
42	 * first backup on its next pass.
43	 */
44	export async function setBackupSchedule(
45	  serverId: string,
46	  enabled: boolean,
47	  intervalHours: number
48	): Promise<{ error?: string }> {
49	  const { user, server } = await ownedServer(serverId);
50	
51	  if (enabled && !BACKUP_INTERVAL_CHOICES.includes(intervalHours as any)) {
52	    return { error: "Choose a valid backup interval." };
53	  }
54	
55	  await db.server.update({
56	    where: { id: server.id },
57	    data: {
58	      autoBackup: enabled,
59	      backupIntervalHours: enabled ? intervalHours : null,
60	    },
61	  });
62	  await db.auditLog.create({
63	    data: {
64	      userId: user.id,
65	      action: "server.backup_schedule",
66	      detail: enabled ? `${serverId} every ${intervalHours}h` : `${serverId} disabled`,
67	    },
68	  });
69	  revalidatePath(`/dashboard/servers/${serverId}`);
