73	// ---------- 2. Reinstall to a different OS ----------
74	
75	/**
76	 * Switch the server to a different OS image and reinstall. This ERASES all data:
77	 * the worker's REINSTALL handler destroys the VM and re-provisions it from
78	 * `Server.osTemplateId`, so we persist the new template BEFORE enqueuing.
79	 */
80	export async function reinstallToOs(
81	  serverId: string,
82	  osTemplateId: string
83	): Promise<{ error?: string }> {
84	  const { user, server } = await ownedServer(serverId);
85	
86	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
87	    return { error: "Server must be running or stopped to reinstall." };
88	  }
89	
90	  const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
91	  if (!os?.active) return { error: "That operating system isn't available." };
92	  if (os.id === server.osTemplateId) {
93	    return { error: "This server is already running that operating system." };
94	  }
95	  if (server.plan.ramMB < os.minRamMB) {
96	    return { error: `${os.name} needs at least ${os.minRamMB / 1024} GB RAM — your plan has ${server.plan.ramMB / 1024} GB.` };
97	  }
98	  if (server.plan.diskGB < os.minDiskGB) {
99	    return { error: `${os.name} needs at least ${os.minDiskGB} GB disk — your plan has ${server.plan.diskGB} GB.` };
100	  }
101	
102	  if (await hasInflightJob(serverId)) {
103	    return { error: "Another operation is already in progress on this server." };
104	  }
105	
106	  // A reinstall destroys and re-clones the VM (same vmid). Its disks — including
107	  // any block-storage volume disk (vm-<vmid>-disk-N) — are purged with it. A
108	  // *detached* volume still keeps its disk under this vmid (Proxmox "unused"), so
109	  // purge wipes it too. Refuse while ANY volume is pinned to this server so the
110	  // customer must delete it (which cleanly destroys just that disk) first.
111	  const pinnedVolumes = await db.volume.count({ where: { serverId } });
112	  if (pinnedVolumes > 0) {
113	    const n = pinnedVolumes === 1 ? "volume" : `${pinnedVolumes} volumes`;
114	    return {
115	      error:
116	        `This server still has ${pinnedVolumes === 1 ? "a" : pinnedVolumes} block-storage ${n}. ` +
117	        `Detaching isn't enough — the disk stays on this server, so a reinstall would erase it too. ` +
118	        `To KEEP the data, attach the ${pinnedVolumes === 1 ? "volume" : "volumes"} to a different server first; ` +
119	        `to discard it, delete the ${pinnedVolumes === 1 ? "volume" : "volumes"} from the Volumes page. Then reinstall.`,
120	    };
121	  }
122	
123	  // Persist the target OS and enqueue the rebuild ATOMICALLY.
124	  //
125	  // The REINSTALL handler re-provisions from `Server.osTemplateId`, so the write
126	  // has to land before the job — but as two separate statements a failure between
127	  // them left the row claiming an operating system the VM is not running, with no
128	  // job to make it true. Every page, every support view and the next reinstall
129	  // would then read that row and believe it. One transaction: either the server
130	  // is recorded as the new image AND a rebuild is queued, or neither happened.
131	  await db.$transaction([
132	    db.server.update({ where: { id: server.id }, data: { osTemplateId: os.id } }),
133	    db.job.create({ data: { type: "REINSTALL", serverId } }),
134	  ]);
135	  await db.auditLog.create({
136	    data: {
137	      userId: user.id,
138	      action: "server.reinstall_os",
139	      detail: `${serverId} -> ${os.slug} (was ${server.osTemplate.slug})`,
140	    },
141	  });
142	  revalidatePath(`/dashboard/servers/${serverId}`);
143	  return {};
144	}
145	
146	// ---------- 3. Resize-down ----------
147	
148	/**
149	 * Move a server to a SMALLER (cheaper) plan. CPU/RAM can shrink freely, but the
150	 * disk can NOT shrink on the hypervisor, so we require the target plan's disk to
151	 * be >= the current plan's disk (the worker's RESIZE handler hard-fails a shrink
152	 * otherwise). A prorated credit for the price difference over the remaining term
153	 * is returned to the wallet.
154	 */
155	export async function resizeServerDown(
156	  serverId: string,
157	  newPlanId: string
158	): Promise<{ error?: string }> {
159	  // Money path: this MOVES money (a prorated credit into the wallet) and it
160	  // permanently gives up capacity the customer paid for. `cancelTransferIn`
161	  // guards its credit the same way; this one did not, so an admin impersonating
162	  // a customer could downgrade their server and cash the remaining term out into
163	  // a balance the customer never asked to convert.
164	  await assertNotImpersonating();
165	  const { user, server } = await ownedServer(serverId);
166	
167	  const newPlan = await db.plan.findUnique({ where: { id: newPlanId } });
168	  if (!newPlan?.active) return { error: "Plan not available." };
169	  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
170	  // A GAME server cannot be prorated against its base VPS plan — and THIS is the
171	  // credit path, so this is the dangerous half.
172	  //
173	  // A game tier carries BOTH a `planId` and a `gamePlanId`, and is sold at
174	  // `gamePlan.priceCents`: a FLAT all-in price, typically LOWER than the base plan
175	  // it runs on. `orderGameServer` correctly records `termPromoPercent: 0`, because
176	  // a flat price is not a discounted one. So the credit below is computed from the
177	  // BASE plan's full monthly rate for every remaining month.
178	  //
179	  // lib/proration.ts rests on exactly one invariant — a prorated credit is
180	  // strictly less than the cash actually collected for those months — and this
181	  // breaks it. A $9.99/mo flat tier on a $20.99 base plan pays out $20.99-worth
182	  // per remaining month: real wallet money the customer never paid, self-service,
183	  // repeatable.
184	  //
185	  // Until now it was blocked ONLY by the disk-monotonic guard below, because in a
186	  // catalogue where price and disk both rise there is no cheaper plan with
187	  // equal-or-larger disk. That is a coincidence of the price list, not a
188	  // protection — one cheap high-disk plan opens it. Refusing outright matches how
189	  // `renewalCharge` already treats a game plan: all-in, no add-on lines.
190	  if (server.gamePlanId) {
191	    return {
192	      error:
193	        "Game server plans are fixed bundles — switch tiers from the game server's own settings, or contact support.",
194	    };
195	  }
196	  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };
197	
198	  // This action is downgrades only — upgrades go through resizeServer().
199	  if (newPlan.priceCents >= server.plan.priceCents) {
200	    return { error: "This is not a smaller plan — use the upgrade flow instead." };
201	  }
202	  // Disk can't shrink destructively; block the move rather than lose data.
203	  // Compares PLAN disks on purpose: any purchased `extraDiskGB` is additive to
204	  // both the old and the new plan and is preserved verbatim across the resize, so
205	  // "new plan disk >= old plan disk" is exactly the condition for "effective disk
206	  // does not shrink". Nothing here ever writes extraDiskGB.
207	  if (newPlan.diskGB < server.plan.diskGB) {
208	    return {
209	      error: `Disk can't shrink — ${newPlan.name} has a ${newPlan.diskGB} GB disk but your server uses ${server.plan.diskGB} GB. Pick a smaller plan whose disk is at least ${server.plan.diskGB} GB.`,
210	    };
211	  }
212	
213	  if (await hasInflightJob(serverId)) {
214	    return { error: "Another operation is already in progress on this server." };
215	  }
216	
217	  // Credit at the SAME effective rate the upgrade path charges at (term discount
218	  // plus `server.termPromoPercent`, the rate THIS term was actually sold at) over
219	  // the SAME remaining duration — every month left on `expiresAt`, uncapped,
220	  // exactly as lib/resize.ts charges for. Both directions read that one persisted
221	  // scalar off the same row, which is what makes a round trip net to zero no matter
222	  // what dates the two halves happen on. Until 2026-07-26 the rate came from
223	  // `currentPromo(now)` instead, so a customer could upgrade under the 45% Cyber
224	  // Monday basis and downgrade under the 15% Launch Sale basis and keep the spread
225	  // on every remaining month, once per promo cycle, forever.
226	  //
227	  // The old maths credited the raw LIST-price delta, so it refunded more than the
228	  // customer had ever paid (they bought at the term-discounted, promo-reduced
229	  // price). Pricing both directions through lib/proration.ts fixed the RATE, but
230	  // this line then capped the DURATION at one term while the upgrade side did not,
231	  // which broke the round trip the other way: a customer whose stacked "Renew now"
232	  // had pushed `expiresAt` 36 months out on a 12-month term paid $544.32 to
233	  // upgrade Starter -> Max and got only $181.44 back coming straight down, so the
234	  // platform pocketed $362.88 of months they had genuinely paid for. `expiresAt`
235	  // never advances without payment, so all of those months are owed back. The cap
236	  // argument has been removed from `remainingMonths` outright — the two directions
237	  // now cannot express different durations.
238	  let creditCents = 0;
239	  if (!server.isFree && server.expiresAt) {
240	    creditCents = prorateDowngradeCreditCents({
241	      fromMonthlyCents: server.plan.priceCents,
242	      toMonthlyCents: newPlan.priceCents,
243	      termMonths: server.termMonths,
244	      termPromoPercent: server.termPromoPercent,
245	      // Mirror the upgrade charge (lib/resize.ts): an annual server credits at the
246	      // SAME admin discount it was sold at, so the round trip cannot mint or lose money.
247	      annualDiscountPct: await annualDiscountPct(),
248	      monthsRemaining: remainingMonths(server.expiresAt, Date.now()),
249	    });
250	  }
251	
252	  await db.$transaction([
253	    ...(creditCents > 0
254	      ? [
255	          db.user.update({
256	            where: { id: server.userId },
257	            data: { balanceCents: { increment: creditCents } },
258	          }),
259	          db.walletTransaction.create({
260	            data: {
261	              userId: server.userId,
262	              amountCents: creditCents,
263	              description: `Downgrade to ${newPlan.name} (prorated credit) — ${server.hostname}`,
264	            },
265	          }),
