93	export async function purchaseDomain(prev: any, formData: FormData): Promise<{ error?: string }> {
94	  // Spend path: registering a domain debits the wallet AND buys a non-refundable
95	  // asset from a registrar in the customer's name, with registrant contact details
96	  // taken from this form. `submitTransferIn` — the same product, the same money —
97	  // has carried this guard since it was written; registration and renewal never did.
98	  await assertNotImpersonating();
99	  const user = await requireUser();
100	  // Purchase gate: an unverified address means we cannot reach the person we
101	  // are about to charge. See lib/email-verification.ts.
102	  const unverified = await emailVerificationError(user);
103	  if (unverified) return { error: unverified };
