105	  if (!(await getSettingBool("feature_domains", true))) {
106	    return { error: "Domain registration is currently unavailable." };
107	  }
108	  if (!registrarConfigured()) {
109	    return { error: "Domain registration is not configured yet (name.com API keys missing)." };
110	  }
