495	/**
496	 * One-click: point apex + www at the platform's public IP.
497	 *
498	 * ADD BEFORE DELETE, per host. This used to delete every apex/www A record and
499	 * only then add the replacements — so a registrar hiccup, a rate limit or a
500	 * network blip in between took the domain DARK and left it that way, with an
501	 * error message that did not say the old records were already gone. That is the
502	 * "six domains dark while the run scored 4/4" failure shape: destructive work
503	 * done first, on the assumption the constructive half cannot fail.
504	 *
505	 * The new order is also idempotent — an A record already pointing at `ip` is
506	 * kept rather than churned — so clicking twice is free, and a half-finished run
507	 * can simply be retried.
508	 */
509	export async function pointDomainAtServer(domainId: string): Promise<{ error?: string }> {
510	  let ctx;
511	  try {
512	    ctx = await ownedDomain(domainId);
513	  } catch (e: any) {
514	    return { error: e.message };
515	  }
516	  const ip = process.env.PUBLIC_IP;
517	  if (!ip) {
518	    return {
519	      error:
520	        "This platform doesn't have a public IP configured, so there is nothing to point the domain at. " +
521	        "Contact support — this is a platform configuration problem, not something you can fix from here.",
522	    };
523	  }
524	
525	  const done: string[] = [];
526	  try {
527	    const recs = await listRecords(ctx.domain.name);
528	    for (const host of ["", "www"]) {
529	      const label = host === "" ? ctx.domain.name : `www.${ctx.domain.name}`;
530	      const existing = recs.filter((r) => r.host === host && r.type === "A");
531	      const keep = existing.find((r) => r.answer === ip);
532	      // Constructive half FIRST: the name resolves somewhere at every instant.
533	      if (!keep) await addRecord(ctx.domain.name, { host, type: "A", answer: ip, ttl: 300 });
534	      // Only now retire the records that point elsewhere.
535	      for (const r of existing) {
536	        if (keep && r.id === keep.id) continue;
537	        await deleteRecord(ctx.domain.name, r.id);
538	      }
539	      done.push(label);
540	    }
541	  } catch (e: any) {
542	    const reason = String(e?.message ?? e).slice(0, 200);
543	    return {
544	      error:
545	        `Your DNS provider rejected part of this change (${reason}). ` +
546	        (done.length > 0
547	          ? `${done.join(" and ")} ${done.length === 1 ? "was" : "were"} pointed at ${ip} and ${done.length === 1 ? "is" : "are"} live; the rest was not changed. `
548	          : "Nothing was changed and your existing records are untouched. ") +
549	        `Wait a minute and click Point at server again — it is safe to repeat.`,
550	    };
551	  }
552	  revalidatePath(`/dashboard/domains/${domainId}`);
553	  return {};
554	}
