498	    data: { userId: ctx.user.id, action: "domain.registrar_lock", detail: `${ctx.domain.name} -> ${locked ? "locked" : "unlocked"}${live ? " (live)" : ""}` },
499	  });
500	  revalidatePath(`/dashboard/domains/${domainId}`);
501	  return { locked, live, note };
