29	const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;
30	
31	/** Statuses a customer may retry a transfer over (nothing live is clobbered). */
32	const RETRYABLE = ["FAILED", "TRANSFER_FAILED"] as const;
33	
34	function errMsg(e: unknown): string {
35	  return String(e instanceof Error ? e.message : e).slice(0, 200);
36	}
37	
38	/** Never let a registrar error echo the customer's auth code back into the UI/logs. */
39	function scrubbed(msg: string, authCode: string): string {
40	  return authCode ? msg.split(authCode).join("***") : msg;
