52	/* ------------------------------------------------------------------ *
53	 * Step 1 — quote
54	 * ------------------------------------------------------------------ */
55	
56	export type TransferQuote = {
57	  domain: string;
58	  transferable: boolean;
59	  reason: string | null;
60	  /** RETAIL total the customer pays — the transfer plus a 1-year extension. */
61	  priceCents: number | null;
62	};
63	
64	/**
65	 * Is this domain transferable, and what does it cost? Read-only; safe to call
66	 * repeatedly from the wizard. Rate-limited because every call fans out to the
67	 * registrar.
68	 */
69	export async function quoteTransferIn(raw: string): Promise<{ error?: string; quote?: TransferQuote }> {
70	  const user = await requireUser();
71	  if (!(await getSettingBool("feature_domains", true))) {
72	    return { error: "Domain transfers are currently unavailable." };
73	  }
74	  if (!transfersAvailable()) {
75	    return { error: "Domain transfers aren't configured yet (registrar API keys missing)." };
76	  }
77	  const rl = checkRateLimit(`domain-transfer-quote:${user.id}`, { max: 20, windowMs: 60_000 });
78	  if (!rl.ok) return { error: `Too many lookups — try again in ${rl.retryAfterSec}s.` };
79	
80	  const domain = raw.toLowerCase().trim().replace(/^https?:\/\//, "").replace(/\/.*$/, "");
81	  if (!DOMAIN_RE.test(domain)) return { error: "Enter a domain like example.com (no www, no path)." };
82	
83	  const existing = await db.domain.findUnique({ where: { name: domain } });
84	  if (existing) {
85	    if (existing.userId !== user.id) return { error: "This domain is already managed by another account." };
86	    if (existing.status === "TRANSFER_PENDING") {
87	      return { error: "A transfer for this domain is already in progress on your account." };
88	    }
89	    if (!RETRYABLE.includes(existing.status as (typeof RETRYABLE)[number])) {
90	      return { error: `${domain} is already on your account (status: ${existing.status.toLowerCase()}).` };
91	    }
92	  }
93	
94	  let check: TransferCheck;
95	  try {
96	    check = await checkTransfer(domain);
97	  } catch (e) {
98	    return { error: errMsg(e) };
99	  }
100	  return {
101	    quote: {
102	      domain,
103	      transferable: check.transferable && check.priceCents !== null,
104	      reason: check.reason,
105	      priceCents: check.priceCents === null ? null : transferChargeCents(check.priceCents),
106	    },
107	  };
108	}
109	
110	/* ------------------------------------------------------------------ *
111	 * Steps 2-4 — pre-flight, auth code, submit
112	 * ------------------------------------------------------------------ */
113	
114	/**
115	 * Submit an inbound transfer.
116	 *
117	 * ORDER MATTERS — the registrar is called BEFORE any money moves:
118	 *   1. re-quote server-side (the price the client showed is never trusted),
119	 *   2. `createTransfer` at the registrar,
120	 *   3. debit + invoice + Domain row, all in ONE transaction.
121	 *
122	 * So a charge for a transfer that was never submitted is structurally
123	 * impossible. A double charge is impossible three ways over: the in-process
124	 * guard blocks the double-click, `Domain.name` is UNIQUE inside the charging
125	 * transaction (and the retry path CAS-swaps off the exact status we read), and
126	 * name.com itself refuses a second transfer for a domain already in flight.
127	 *
128	 * If the debit fails after a successful submit (balance drained in the seconds
129	 * between the check and the charge) we cancel the transfer back out at the
130	 * registrar rather than quietly performing work nobody paid for.
131	 */
132	export async function submitTransferIn(prev: any, formData: FormData): Promise<{ error?: string }> {
133	  const user = await requireUser();
134	  // Spend path: never move a customer's money while an admin is impersonating.
135	  await assertNotImpersonating();
136	  // Purchase gate: an unverified address means we cannot reach the person we
137	  // are about to charge. See lib/email-verification.ts.
138	  const unverified = await emailVerificationError(user);
139	  if (unverified) return { error: unverified };
140	
141	  if (!(await getSettingBool("feature_domains", true))) {
142	    return { error: "Domain transfers are currently unavailable." };
143	  }
144	  if (!transfersAvailable()) {
145	    return { error: "Domain transfers aren't configured yet (registrar API keys missing)." };
146	  }
147	  const rl = checkRateLimit(`domain-transfer-in:${user.id}`, { max: 5, windowMs: 10 * 60_000 });
148	  if (!rl.ok) {
149	    return { error: `Too many transfer attempts — try again in ${Math.ceil(rl.retryAfterSec / 60)} min.` };
150	  }
151	
152	  const domain = String(formData.get("domain") ?? "").toLowerCase().trim();
153	  if (!DOMAIN_RE.test(domain)) return { error: "Invalid domain name." };
154	
155	  const authCode = String(formData.get("authCode") ?? "").trim();
156	  if (authCode.length < 4 || authCode.length > 255) {
157	    return { error: "Enter the EPP / auth code from your current registrar (4–255 characters)." };
158	  }
159	
160	  // The pre-flight checklist is a real gate, not decoration: the registry will
161	  // reject a transfer that fails any of these, and the customer eats a 5-7 day
162	  // round trip for nothing. Confirm every box came back ticked.
163	  const acks = ["ackUnlocked", "ackPrivacy", "ackAge", "ackApproval"];
164	  if (acks.some((k) => formData.get(k) !== "1")) {
165	    return { error: "Confirm every pre-flight item before we submit the transfer." };
166	  }
167	
168	  const expectedCents = Math.round(Number(formData.get("expectedCents") ?? 0));
169	
170	  const guardKey = `transfer-in:${user.id}:${domain}`;
171	  if (!beginTransferSubmit(guardKey)) {
172	    return { error: "That transfer is already being submitted — give it a moment before retrying." };
173	  }
174	
175	  try {
176	    const existing = await db.domain.findUnique({ where: { name: domain } });
177	    if (existing) {
178	      if (existing.userId !== user.id) return { error: "This domain is already managed by another account." };
179	      if (existing.status === "TRANSFER_PENDING") {
180	        return { error: "A transfer for this domain is already in progress — you have not been charged twice." };
181	      }
182	      if (!RETRYABLE.includes(existing.status as (typeof RETRYABLE)[number])) {
183	        return { error: `${domain} is already on your account (status: ${existing.status.toLowerCase()}).` };
184	      }
185	    }
186	
187	    // Re-quote server-side. The wizard's number is a display; this is the price.
188	    let check: TransferCheck;
189	    try {
190	      check = await checkTransfer(domain);
191	    } catch (e) {
192	      return { error: errMsg(e) };
193	    }
194	    if (!check.transferable || check.priceCents === null || check.costCents === null) {
195	      return { error: check.reason ?? "This domain can't be transferred in right now." };
196	    }
197	    const totalCents = transferChargeCents(check.priceCents); // retail — what we charge
198	    const registrarCostCents = check.costCents; // cost — what we tell name.com to spend
199	
200	    if (expectedCents !== totalCents) {
201	      return {
202	        error:
203	          `The registrar's price changed while you were filling this in — it's now $${(totalCents / 100).toFixed(2)}. ` +
204	          `Go back a step to re-check and confirm the new price. Nothing has been charged.`,
205	      };
206	    }
207	    if (user.balanceCents < totalCents) {
208	      return { error: `Insufficient balance — this transfer costs $${(totalCents / 100).toFixed(2)}.` };
209	    }
210	
211	    // ---- Registrar first. No money has moved at this point. ----
212	    let submitted;
213	    try {
214	      submitted = await createTransfer(domain, authCode, registrarCostCents);
215	    } catch (e) {
216	      return { error: `The registrar refused the transfer: ${scrubbed(errMsg(e), authCode)} (you were not charged).` };
217	    }
218	
219	    // Recorded BEFORE the charge so that even a hard crash here leaves ops a
220	    // trace of a transfer that is live at the registrar but not yet billed.
221	    await db.auditLog
222	      .create({
223	        data: {
224	          userId: user.id,
225	          action: "domain.transfer_in.submitted",
226	          detail: `${domain} status=${submitted.status} charge=${totalCents}c`,
227	        },
228	      })
229	      .catch(() => {});
230	
231	    // ---- Charge + row, atomically. ----
232	    let domainId: string;
233	    try {
234	      domainId = await db.$transaction(async (tx) => {
235	        const transferData = {
236	          status: "TRANSFER_PENDING" as const,
237	          isTransferIn: true,
238	          transferAuthCodeEnc: encryptSecret(authCode),
239	          transferStartedAt: new Date(),
240	          transferStatus: submitted.status,
241	          transferEmail: submitted.email,
242	          priceCents: check.priceCents!,
243	          costCents: check.costCents!,
244	          termYears: TRANSFER_TERM_YEARS,
245	          registrar: "name.com",
246	          error: null,
247	        };
248	        // Write the row FIRST: a unique conflict or a lost CAS aborts the whole
249	        // transaction before the wallet is touched.
250	        let id: string;
251	        if (existing) {
252	          const swapped = await tx.domain.updateMany({
253	            where: { id: existing.id, status: existing.status },
254	            data: transferData,
255	          });
256	          if (swapped.count === 0) throw new DuplicateDomainError();
257	          id = existing.id;
258	        } else {
259	          const created = await tx.domain.create({
260	            data: { name: domain, userId: user.id, ...transferData },
261	          });
262	          id = created.id;
263	        }
264	        await debitWallet(tx, user.id, totalCents);
265	        await tx.walletTransaction.create({
266	          data: {
267	            userId: user.id,
268	            amountCents: -totalCents,
269	            description: transferChargeDescription(domain),
270	          },
271	        });
272	        await tx.invoice.create({
273	          data: invoiceCreateData({
274	            userId: user.id,
275	            description: transferChargeDescription(domain),
276	            status: "PAID",
277	            lineItems: [
278	              {
279	                description: `Domain transfer in — ${domain} (adds 1 year to the registration)`,
280	                qty: 1,
281	                unitCents: totalCents,
282	                amountCents: totalCents,
283	              },
284	            ],
285	          }),
286	        });
287	        return id;
288	      });
289	    } catch (e) {
290	      // The transfer IS live at the registrar but we could not bill it. Undo the
291	      // submission rather than do unpaid work; if the registrar won't cancel,
292	      // flag it for ops instead of silently swallowing it.
293	      let cancelled = false;
294	      try {
295	        await cancelTransfer(domain);
296	        cancelled = true;
297	      } catch {
298	        /* registrar refused the cancel — ops has to unwind it manually */
299	      }
300	      await db.auditLog
301	        .create({
302	          data: {
303	            userId: user.id,
304	            action: "domain.transfer_in.uncharged",
305	            detail: `${domain}: submitted but not charged (${errMsg(e)}) — cancelled=${cancelled}`.slice(0, 500),
306	          },
307	        })
308	        .catch(() => {});
309	
310	      if (e instanceof InsufficientBalanceError) {
311	        return {
312	          error: cancelled
313	            ? "Your balance dropped below the transfer price before we could charge it, so we cancelled the transfer at the registrar. Top up and try again — you were not charged."
314	            : "Your balance dropped below the transfer price before we could charge it. We've flagged this for our team — you were not charged. Please contact support before retrying.",
315	        };
316	      }
317	      if (e instanceof DuplicateDomainError || isUniqueConflict(e)) {
318	        return { error: "A transfer for this domain is already in progress — you have not been charged twice." };
319	      }
320	      throw e;
321	    }
322	
323	    await db.notification
324	      .create({
325	        data: {
326	          userId: user.id,
327	          title: `Transfer started: ${domain}`,
328	          body:
329	            `We've submitted the transfer to the registrar. Inbound transfers normally take 5–7 days ` +
330	            `and you must approve a confirmation email from your CURRENT registrar before it can complete.`,
331	          href: `/dashboard/domains/${domainId}`,
332	        },
333	      })
334	      .catch(() => {});
335	
336	    revalidatePath("/dashboard/domains");
337	    redirect(`/dashboard/domains/${domainId}`);
338	  } finally {
339	    endTransferSubmit(guardKey);
340	  }
341	}
