33	export async function upgradeServerBackupTier(
34	  serverId: string,
35	  tier: string,
36	): Promise<{ error?: string; ok?: boolean }> {
37	  // Spend path: block wallet debits while an admin is impersonating.
38	  await assertNotImpersonating();
39	  const { user } = await ownedServer(serverId);
40	
41	  const target = normalizeBackupTier(tier);
42	  if (target !== "PLUS") return { error: "That backup tier isn't available." };
43	
44	  // Purchase gate: a backup upgrade is a real charge. See lib/email-verification.ts.
45	  const unverified = await emailVerificationError(user);
46	  if (unverified) return { error: unverified };
47	
48	  // Validate + price (ownership already checked). Surfaces the friendly guard message.
49	  let quote;
50	  try {
51	    quote = await backupUpgradeQuote(serverId, target);
52	  } catch (e) {
53	    if (e instanceof BackupUpgradeError) return { error: e.message };
54	    throw e;
55	  }
