57	  // Wallet-only in the MVP: reject up front with a clear number if the balance
58	  // can't cover the proration, rather than throwing an opaque insufficiency later.
59	  if (!quote.server.isFree && quote.prorateCents > user.balanceCents) {
60	    return {
61	      error:
62	        `Upgrading to Plus backups costs $${(quote.prorateCents / 100).toFixed(2)} for the rest of your term, ` +
63	        `and card payments aren't set up for this change yet — top up your wallet first.`,
64	    };
65	  }
66	
67	  try {
68	    await applyBackupUpgrade({ serverId, targetTier: target, actorUserId: user.id });
69	  } catch (e) {
70	    if (e instanceof BackupUpgradeError) return { error: e.message };
71	    if (e instanceof InsufficientBalanceError) {
72	      return { error: "Insufficient balance — top up your wallet first." };
73	    }
74	    throw e;
75	  }
76	  revalidatePath(`/dashboard/servers/${serverId}`);
77	  return { ok: true };
