149	    ? await db.job.findMany({
150	        where: { type: "BACKUP_CREATE", serverId: { in: ids } },
151	        orderBy: { createdAt: "desc" },
152	        select: { serverId: true, createdAt: true, status: true },
153	      })
154	    : [];
155	  const lastAttempt = new Map<string, { at: Date; status: string }>();
156	  for (const j of attempts) {
157	    if (j.serverId && !lastAttempt.has(j.serverId)) {
