159	    }
160	  }
161	
162	  const serverRows: ServerScheduleRow[] = servers.map((s) => ({
163	    id: s.id,
164	    vmid: s.vmid,
165	    hostname: s.hostname,
166	    email: s.user?.email ?? "—",
167	    nodeLabel: s.node?.name ?? null,
168	    status: s.status,
169	    autoBackup: s.autoBackup,
170	    backupIntervalHours: s.backupIntervalHours,
171	    lastAutoBackup: s.lastAutoBackup ? s.lastAutoBackup.toISOString() : null,
