196	/**
197	 * Enqueue a BACKUP_RESTORE for `volid` against `serverId`.
198	 *
199	 * The volid is NEVER trusted: it must (1) name this server's vmid structurally
200	 * and (2) actually be present in the live listing of that vmid's archives on the
201	 * server's own node. A recycled or mismatched volid restoring a stranger's root
202	 * filesystem onto this VM — handing over their databases, secrets and /etc/shadow
203	 * — is precisely the class of bug documented in lib/proxmox.ts `pickProvisionVmid`.
204	 */
205	export async function adminRequestRestore(
206	  serverId: string,
207	  volid: string
208	): Promise<{ ok?: boolean; error?: string }> {
209	  const admin = await requireArea("fleet");
210	
211	  const server = await db.server.findUnique({
212	    where: { id: serverId },
213	    include: { node: true },
214	  });
215	  if (!server) return { error: "Server not found." };
216	  if (!server.vmid) return { error: "Server has no VM yet." };
217	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
218	    return { error: "Server must be running or stopped to restore a backup." };
219	  }
220	
221	  // (1) Structural: the volid must name THIS server's vmid.
222	  const named = vmidFromVolid(volid);
223	  if (named === null || named !== server.vmid) {
224	    return { error: "That backup does not belong to this server." };
225	  }
226	
227	  // (2) Authoritative: the archive must exist for this vmid, read from the
228	  // server's own node (vmids can collide across nodes, so the primary is wrong
229	  // for a server pinned elsewhere).
230	  let owned: { volid?: string }[];
231	  try {
232	    if (server.node) {
233	      const client = pveFor({
234	        apiUrl: server.node.apiUrl,
235	        pveNode: server.node.pveNode,
236	        tokenId: server.node.tokenId,
237	        tokenSecret: server.node.tokenSecret,
238	      });
239	      owned = await listBackupsOn(client, server.vmid);
240	    } else {
241	      owned = (await listBackups(server.vmid)) as { volid?: string }[];
242	    }
243	  } catch {
244	    return { error: "Could not verify the backup — the hypervisor is briefly unavailable." };
245	  }
246	  if (!owned.some((b) => b.volid === volid)) {
247	    return { error: "That backup was not found for this server." };
248	  }
249	
250	  // No concurrent job — the worker is serial and restore overwrites the disk.
251	  const pending = await db.job.count({
252	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
253	  });
254	  if (pending > 0) {
255	    return { error: "Another operation is already in progress on this server." };
256	  }
257	
258	  await db.job.create({ data: { type: "BACKUP_RESTORE", serverId, payload: { volid } } });
259	  await db.auditLog.create({
260	    data: { userId: admin.id, action: "admin.backup_restore", detail: `${serverId} ${volid}` },
261	  });
262	  revalidatePath("/admin/backups");
263	  return { ok: true };
264	}
