144	/** All of the current user's SSL certificates, newest first. */
145	export async function listCertificates(): Promise<SslCertificate[]> {
146	  const user = await requireUser();
147	  return db.sslCertificate.findMany({
148	    where: { userId: user.id },
149	    orderBy: { createdAt: "desc" },
150	  });
151	}
