305	/** Create a scoped database for an account (within the plan's maxDatabases). */
306	export async function createHostingDatabase(accountId: string, label: string): Promise<{ error?: string; ok?: boolean; password?: string }> {
307	  const user = await requireUser();
308	  await assertNotImpersonating();
309	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, username: true, maxDatabases: true } });
310	  if (!a) return { error: "Account not found." };
311	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
312	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
313	  // A short, safe suffix keyed off the account username: <user>_<slug>.
314	  const slug = String(label ?? "").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db";
315	  const name = `${a.username}_${slug}`.slice(0, 64);
316	  const dbUser = name.slice(0, 32);
317	  if (!/^[a-z0-9_]{1,64}$/.test(name)) return { error: "Invalid database name." };
318	  const password = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
319	  // Count + create in ONE serializable transaction, so concurrent creates can't
320	  // both read a stale count and blow past the plan cap (audit 2026-08-01 TOCTOU).
321	  try {
322	    await db.$transaction(async (tx) => {
323	      const n = await tx.hostingDatabase.count({ where: { accountId: a.id, status: { in: ["PENDING", "ACTIVE"] } } });
324	      if (n >= a.maxDatabases) throw new Error("CAP");
325	      await tx.hostingDatabase.create({ data: { accountId: a.id, name, dbUser, passwordEnc: encryptSecret(password), status: "PENDING" } });
326	    }, { isolationLevel: "Serializable" });
327	  } catch (e) {
328	    if (e instanceof Error && e.message === "CAP") return { error: `Your plan allows ${a.maxDatabases} database${a.maxDatabases === 1 ? "" : "s"}.` };
329	    // Serialization conflict (P2034) or the unique(accountId,name) collision.
330	    return { error: "A database with that name already exists, or the request raced — try again." };
331	  }
332	  revalidatePath("/dashboard/hosting");
333	  // Shown ONCE — the encrypted copy is cleared by the provisioner after it applies it.
334	  return { ok: true, password };
335	}
