778	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_ADDON_DOMAIN", payload: JSON.stringify({ addonId: addon.id }) } });
779	    }, { isolationLevel: "Serializable" });
780	  } catch (e) {
781	    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
782	    return { error: "That domain is already added, or the request raced — try again." };
783	  }
