188	/**
189	 * Save identity + signature onto the mailbox row. Only the fields actually
190	 * present in `input` are written, so the Identity and Signature sub-forms can
191	 * each save independently without clobbering the other's data.
192	 *
193	 * Signature HTML is sanitised server-side with `safeHtml` (defence in depth —
194	 * the client sanitises too) and a plain-text version is derived into the legacy
195	 * `signature` column so the text/plain MIME part always has a fallback.
196	 */
197	export async function saveMailboxSettings(
198	  input: {
199	    displayName?: string;
200	    replyTo?: string;
201	    organization?: string;
202	    signatureHtml?: string;
203	    signatureEnabled?: boolean;
204	    signatureOnReply?: boolean;
205	    signaturePlacement?: string;
206	  },
207	  mailboxAddress?: string,
208	): Promise<Result> {
209	  const { user, mailboxId } = await resolveMailbox(mailboxAddress);
210	  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
211	  if (limited) return limited;
212	
213	  const data: {
214	    displayName?: string | null;
215	    replyTo?: string | null;
216	    organization?: string | null;
217	    signatureHtml?: string | null;
218	    signature?: string | null;
219	    signatureEnabled?: boolean;
220	    signatureOnReply?: boolean;
221	    signaturePlacement?: string;
222	  } = {};
223	
224	  if (input.displayName !== undefined) {
225	    const displayName = input.displayName.trim();
226	    if (displayName.length > 120) return { ok: false, error: "Display name is too long (max 120 characters)." };
227	    data.displayName = displayName || null;
228	  }
229	
230	  if (input.replyTo !== undefined) {
231	    const replyTo = input.replyTo.trim();
232	    if (replyTo && !EMAIL_RE.test(replyTo)) return { ok: false, error: "Reply-to must be a valid email address." };
233	    data.replyTo = replyTo || null;
234	  }
235	
236	  if (input.organization !== undefined) {
237	    const organization = input.organization.trim();
238	    if (organization.length > 200) return { ok: false, error: "Organization is too long (max 200 characters)." };
239	    data.organization = organization || null;
240	  }
241	
242	  if (input.signatureHtml !== undefined) {
243	    const clean = safeHtml(input.signatureHtml);
244	    if (clean.length > SIGNATURE_HTML_MAX) {
245	      return { ok: false, error: "Signature is too long. Please shorten it." };
246	    }
247	    data.signatureHtml = clean || null;
248	    const plain = signatureHtmlToText(clean);
249	    data.signature = plain ? plain : null;
250	  }
251	
252	  if (input.signatureEnabled !== undefined) data.signatureEnabled = Boolean(input.signatureEnabled);
253	  if (input.signatureOnReply !== undefined) data.signatureOnReply = Boolean(input.signatureOnReply);
254	  if (input.signaturePlacement !== undefined) {
