264	// ---------------------------------------------------------------------------
265	// Server-side rules: auto-reply + forwarding, as real Mailcow sieve filters
266	// ---------------------------------------------------------------------------
267	//
268	// These two were STORE-ONLY: the panel wrote the DB, showed a green "Saved",
269	// and NOTHING on the mail server changed. A customer switching on an
270	// out-of-office before a holiday got no auto-replies and no forwarded mail. The
271	// old comments claimed the API had no primitive for this; it does —
272	// `POST /add|edit|delete/filter` drives Dovecot sieve per mailbox (see
273	// lib/mail/sieve.ts for the capability audit).
274	//
275	// The whole rule set is compiled into ONE managed script and pushed BEFORE the
276	// DB is written, so the stored preference and the live server never disagree.
277	// If Mailcow rejects the push the DB is left untouched and the customer sees the
278	// failure — the opposite of the "Saved" lie this replaces.
279	
280	/** Live state of the managed sieve script, read back from the mail server. */
281	export type MailRuleStatus = {
282	  /** Rules can be enforced at all (Mailcow configured + reachable + domain verified). */
283	  supported: boolean;
284	  /** The server is currently running our auto-reply / forwarding rule. */
285	  autoReplyLive: boolean;
286	  forwardingLive: boolean;
287	  /** Why enforcement is unavailable, when it is. */
288	  error?: string;
289	};
