291	/** Load the rule columns for a mailbox we have already ownership-checked. */
292	async function ruleState(mailboxId: string, address: string): Promise<MailboxRuleState> {
293	  const row = await loadMailboxRow(mailboxId);
294	  return {
295	    address,
296	    autoReplyEnabled: row?.autoReplyEnabled ?? false,
297	    autoReplySubject: row?.autoReplySubject ?? null,
298	    autoReplyBody: row?.autoReplyBody ?? null,
299	    autoReplyStart: row?.autoReplyStart ?? null,
300	    autoReplyEnd: row?.autoReplyEnd ?? null,
301	    forwardingAddress: row?.forwardingAddress ?? null,
302	    forwardKeepCopy: row?.forwardKeepCopy ?? true,
303	  };
304	}
