306	/**
307	 * Push `state` to Mailcow as the mailbox's single managed sieve filter.
308	 *
309	 * Idempotent: reuses our existing filter when there is one, prunes duplicates
310	 * left by an interrupted save, and DELETES the filter when nothing is enabled so
311	 * switching a rule off really switches it off on the server.
312	 *
313	 * Only ever touches a filter whose `script_desc` is ours — a filter an operator
314	 * created by hand in Mailcow's own UI is left completely alone.
315	 *
316	 * Throws on failure; callers translate that into a user-visible error and skip
317	 * the DB write.
318	 */
319	async function pushMailboxSieve(state: MailboxRuleState): Promise<void> {
320	  const script = buildMailboxSieve(state);
321	  const existing = (await mcListFilters(state.address)).filter((f) => isNxeonSieve(f.scriptDesc));
322	
323	  if (!script) {
324	    for (const f of existing) await mcDeleteFilter(f.id);
325	    return;
326	  }
327	
328	  const [keep, ...duplicates] = existing;
329	  for (const f of duplicates) await mcDeleteFilter(f.id);
330	
331	  if (keep) {
332	    await mcEditFilter(keep.id, {
333	      scriptDesc: NXEON_SIEVE_DESC,
334	      scriptData: script,
335	      filterType: NXEON_SIEVE_TYPE,
336	      active: true,
337	    });
338	  } else {
339	    await mcAddFilter({
340	      address: state.address,
341	      scriptDesc: NXEON_SIEVE_DESC,
342	      scriptData: script,
343	      filterType: NXEON_SIEVE_TYPE,
344	      active: true,
345	    });
346	  }
347	}
