349	/**
350	 * Guard shared by both rule savers.
351	 *
352	 * A sieve `redirect` sends a copy of every inbound message somewhere else, so
353	 * this is exactly the primitive a cross-tenant takeover would want. Owning the
354	 * subscription ROW is not proof of owning the DOMAIN (the 2026-07-25 finding),
355	 * so an unverified external domain is refused outright.
356	 */
357	function assertRulesAllowed(sub: {
358	  external: boolean;
359	  verified: boolean;
360	  status: string;
361	}): { ok: false; error: string } | null {
362	  if (!mailcowConfigured()) {
363	    return { ok: false, error: "Mail server is not configured yet — rules can't be applied." };
364	  }
365	  if (sub.status === "CANCELLED") {
366	    return { ok: false, error: "This subscription is cancelled." };
367	  }
368	  if (sub.external && !sub.verified) {
369	    return {
370	      ok: false,
371	      error: "Verify this domain first (Business Email → Verify DNS) before setting up mail rules.",
372	    };
373	  }
374	  return null;
375	}
