404	/**
405	 * Forward inbound mail to another address, enforced by a real sieve `redirect`.
406	 * "Keep a copy" maps to `redirect :copy` (implicit keep survives); without it a
407	 * bare `redirect` + `stop` forwards without local delivery.
408	 */
409	export async function saveForwarding(
410	  input: { enabled: boolean; address?: string; keepCopy?: boolean },
411	  mailboxAddress?: string,
412	): Promise<Result> {
413	  const { user, mailboxId, address, subscription } = await resolveMailbox(mailboxAddress);
414	  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
415	  if (limited) return limited;
416	
417	  const enabled = Boolean(input.enabled);
418	  const target = (input.address ?? "").trim().toLowerCase();
419	  const keepCopy = input.keepCopy !== false;
420	
421	  if (enabled) {
422	    if (!target) return { ok: false, error: "Enter an address to forward to." };
423	    if (!EMAIL_RE.test(target)) return { ok: false, error: "That doesn't look like a valid email address." };
424	    if (target.length > 200) return { ok: false, error: "That address is too long." };
425	    if (target === address.toLowerCase()) return { ok: false, error: "Forwarding to this mailbox itself does nothing." };
426	  }
427	
428	  const blocked = assertRulesAllowed(subscription);
429	  if (blocked) return blocked;
430	
431	  const next: MailboxRuleState = {
432	    ...(await ruleState(mailboxId, address)),
433	    forwardingAddress: enabled && target ? target : null,
434	    forwardKeepCopy: keepCopy,
435	  };
436	
437	  try {
438	    await pushMailboxSieve(next);
439	  } catch (e) {
440	    // Deliberately do NOT persist: a stored "forwarding on" that the server is
441	    // not running is the exact defect this replaces.
442	    return { ok: false, error: `Couldn't apply forwarding on the mail server: ${friendly(e)}` };
443	  }
444	
445	  await updateMailboxRow(mailboxId, {
446	    forwardingAddress: next.forwardingAddress,
447	    forwardKeepCopy: next.forwardKeepCopy,
448	  });
449	
450	  await db.auditLog
451	    .create({
452	      data: {
453	        userId: user.id,
454	        action: "mailbox.forwarding",
455	        detail: `${address} → ${next.forwardingAddress ?? "off"}${next.forwardingAddress && !keepCopy ? " (no local copy)" : ""}`,
456	      },
457	    })
458	    .catch(() => {});
459	
460	  return { ok: true };
461	}
