463	/**
464	 * Out-of-office responder, enforced by a real sieve `vacation`. The date window
465	 * is compiled into the script as a `currentdate` test so the mail server starts
466	 * and stops replying on its own — nothing here runs on a schedule, so a window
467	 * evaluated in this process would simply never stop.
468	 */
469	export async function saveAutoReply(
470	  input: { enabled: boolean; subject?: string; body?: string; start?: string | null; end?: string | null },
471	  mailboxAddress?: string,
472	): Promise<Result> {
473	  const { user, mailboxId, address, subscription } = await resolveMailbox(mailboxAddress);
474	  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
475	  if (limited) return limited;
476	
477	  const enabled = Boolean(input.enabled);
478	  const subject = (input.subject ?? "").trim();
479	  const body = (input.body ?? "").trim();
480	  if (subject.length > 200) return { ok: false, error: "Subject is too long (max 200 characters)." };
481	  if (body.length > 5000) return { ok: false, error: "Message is too long (max 5000 characters)." };
482	  if (enabled && !body) return { ok: false, error: "Add an auto-reply message before turning it on." };
483	
484	  const start = fromDateInput(input.start);
485	  const end = fromDateInput(input.end);
486	  if (start && end && start.getTime() > end.getTime()) {
487	    return { ok: false, error: "The start date must be on or before the end date." };
488	  }
489	
490	  const blocked = assertRulesAllowed(subscription);
491	  if (blocked) return blocked;
492	
493	  const next: MailboxRuleState = {
494	    ...(await ruleState(mailboxId, address)),
495	    autoReplyEnabled: enabled,
496	    autoReplySubject: subject || null,
497	    autoReplyBody: body || null,
498	    autoReplyStart: start,
499	    autoReplyEnd: end,
500	  };
501	
502	  try {
503	    await pushMailboxSieve(next);
504	  } catch (e) {
505	    return { ok: false, error: `Couldn't apply the auto-reply on the mail server: ${friendly(e)}` };
506	  }
507	
508	  await updateMailboxRow(mailboxId, {
509	    autoReplyEnabled: next.autoReplyEnabled,
510	    autoReplySubject: next.autoReplySubject,
511	    autoReplyBody: next.autoReplyBody,
512	    autoReplyStart: next.autoReplyStart,
513	    autoReplyEnd: next.autoReplyEnd,
514	  });
515	
516	  await db.auditLog
517	    .create({
518	      data: {
519	        userId: user.id,
520	        action: "mailbox.autoreply",
521	        detail: `${address} → ${enabled ? "on" : "off"}`,
522	      },
523	    })
524	    .catch(() => {});
525	
526	  return { ok: true };
527	}
