92	/**
93	 * Provision (or re-provision) a mailbox on Mailcow. Never throws — records the
94	 * outcome on the Mailbox row (status ACTIVE on success, FAILED on error) and
95	 * returns it. When Mailcow isn't configured the row is left PROVISIONING so it
96	 * can be picked up once the integration is wired.
97	 */
98	async function provisionMailboxOnMailcow(mailbox: {
99	  id: string;
100	  address: string;
101	  quotaMB: number | null;
102	  subscription: { domainName: string };
103	}): Promise<"ACTIVE" | "FAILED" | "PROVISIONING"> {
104	  if (!mailcowConfigured()) return "PROVISIONING";
105	
106	  const [localPart] = mailbox.address.split("@");
107	  const domain = mailbox.subscription.domainName;
108	  const quotaMB = mailbox.quotaMB ?? 1024;
109	
110	  try {
111	    // Ensure the mail domain exists before adding the mailbox.
112	    if (!(await mcDomainExists(domain))) {
113	      // A concurrent create or pre-existing domain can still error here; ignore
114	      // and let the mailbox add be the real signal.
115	      await mcCreateDomain(domain).catch(() => {});
116	    }
117	
118	    const password = randomBytes(18).toString("base64url");
119	    await mcCreateMailbox({
120	      localPart,
121	      domain,
122	      name: mailbox.address,
123	      password,
124	      quotaMB,
125	    });
126	
127	    await db.mailbox.update({
128	      where: { id: mailbox.id },
129	      data: { status: "ACTIVE", passwordEnc: encryptSecret(password) },
130	    });
131	    return "ACTIVE";
132	  } catch (e) {
133	    await db.mailbox
134	      .update({ where: { id: mailbox.id }, data: { status: "FAILED" } })
135	      .catch(() => {});
136	    console.warn(`[mailcow] provisioning ${mailbox.address} failed:`, e);
137	    return "FAILED";
138	  }
139	}
