239	/**
240	 * Subscribe one of the caller's registered domains to an email plan. Validates
241	 * domain ownership + plan availability, then atomically debits the wallet and
242	 * creates the EmailSubscription with an expiry set from the plan term.
243	 *
244	 * The subscription is created ACTIVE (billing-wise), but no mailboxes are
245	 * provisioned with a mail provider yet — that integration is pending, and the
246	 * UI surfaces every mailbox as "provisioning" until it lands.
247	 */
248	export async function orderEmailHosting(
249	  domainName: string,
250	  emailPlanId: string,
251	): Promise<Result> {
252	  const user = await requireUser();
253	  // Spend path: block while an admin is impersonating, so support cannot buy a
254	  // subscription with a customer's wallet while acting as them.
255	  //
256	  // This was the ONE purchase path in the product without this guard — every
257	  // other spend (order, resize, disk expand, volume, domain register/renew/
258	  // transfer, game plan upgrade, top-up) calls it. Impersonation is meant for
259	  // looking, never for spending: `realUser()` is the admin, `currentUser()` is
260	  // the customer, and a debit taken here would come out of the customer's
261	  // balance with the customer's name on the ledger row.
262	  await assertNotImpersonating();
263	  // Purchase gate: an unverified address means we cannot reach the person we
264	  // are about to charge. See lib/email-verification.ts.
265	  const unverified = await emailVerificationError(user);
266	  if (unverified) return { error: unverified };
267	
268	  const name = String(domainName ?? "")
269	    .trim()
270	    .toLowerCase()
271	    .replace(/\.$/, "");
272	  if (!name) return { error: "Enter a domain." };
273	  if (!domainRe.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };
274	
275	  // Is the domain registered inside Nxeon? If so we control its DNS and can
276	  // treat mail as pre-verifiable; otherwise it's an EXTERNAL domain that must be
277	  // verified via DNS before mail flows.
278	  const inAccount = await db.domain.findFirst({ where: { name, userId: user.id } });
279	  const external = !inAccount;
280	
281	  const plan = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
282	  if (!plan || !plan.active) return { error: "That email plan isn't available." };
283	
284	  // One subscription per domain — ACROSS ALL ACCOUNTS, not just this one.
285	  //
286	  // SECURITY (fixed 2026-07-25): this lookup was scoped to `userId: user.id`,
287	  // which let anyone buy a subscription for a domain another customer already
288	  // held. That was a cross-tenant email takeover: `addMailbox` only checks that
289	  // the SUBSCRIPTION belongs to the caller, and Mailcow keys mailboxes by
290	  // ADDRESS — so an attacker could create admin@victim.com under their own
291	  // subscription, call resetMailboxPassword() (which passes its ownership check
292	  // because the row is theirs), and have the password of the victim's real, live
293	  // mailbox handed back to them. Cost of the attack: the cheapest email plan.
294	  const dupe = await db.emailSubscription.findFirst({
295	    where: { domainName: name, status: { not: "CANCELLED" } },
296	  });
297	  if (dupe) {
298	    return {
299	      error:
300	        dupe.userId === user.id
301	          ? "This domain already has an email subscription."
302	          : "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
303	    };
304	  }
305	
306	  // Seasonal promo = HONEST intro discount on the FIRST term only. The renewal
307	  // path (worker/product-renewals.ts) bills plan.priceCents unchanged, so the
308	  // strikethrough shown on the pricing page is the real renewal price and this
309	  // discounted value is the real first-term price — displayed === charged.
310	  // Managed first-month-free. `promoCharge` mirrors the pre-existing behaviour
311	  // (the first term is free); `fullCharge` is the plan price. The credit is granted
312	  // ONLY if the atomic claim inside the charge tx succeeds — otherwise (already
313	  // redeemed by this account/IP, or the promo is off) the subscription is created
314	  // at FULL price. The eligibility pre-check only picks the balance gate so a
315	  // first-time, $0-balance customer can still subscribe free.
316	  // First-month-free is scoped to Shared Web Hosting only — Business Email always
317	  // bills full. firstMonthFreeAppliesTo("EMAIL") is false, so promoEnabled is false.
318	  const promoEnabled = firstMonthFreeAppliesTo("EMAIL") && (await firstMonthFreeEnabled());
319	  const campaign = promoCampaignFromCookie(await cookies());
320	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
321	  const fullCharge = plan.priceCents;
322	  const promoCharge = 0;
323	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
324	  const anticipated = eligible ? promoCharge : fullCharge;
325	  if (user.balanceCents < anticipated) {
326	    return { error: "Insufficient balance. Top up your wallet first." };
327	  }
328	
329	  try {
330	    await db.$transaction(async (tx) => {
331	      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
332	      let debitCents = fullCharge;
333	      let promoClaimId: string | null = null;
334	      if (promoEnabled) {
335	        const claim = await claimFirstMonthFree(tx, {
336	          userId: user.id,
337	          ipHash,
338	          serviceType: "EMAIL",
339	          campaign,
340	          chargedCents: promoCharge,
341	        });
342	        if (claim.claimed) {
343	          debitCents = promoCharge;
344	          promoClaimId = claim.id;
345	        }
346	      }
347	      const note = debitCents < fullCharge ? " — First month free" : "";
348	      await debitWallet(tx, user.id, debitCents);
349	      await tx.walletTransaction.create({
350	        data: {
351	          userId: user.id,
352	          amountCents: -debitCents,
353	          description: `Business Email: ${plan.name} for ${name}${note}`,
354	        },
355	      });
356	      const sub = await tx.emailSubscription.create({
357	        data: {
358	          userId: user.id,
359	          domainName: name,
360	          emailPlanId: plan.id,
361	          status: "ACTIVE",
362	          autoRenew: true,
363	          expiresAt: addMonths(new Date(), plan.termMonths),
364	          // In-account domains: we control DNS, so treat as verified now. External
365	          // domains: not verified until the customer publishes DNS + we confirm it.
366	          external,
367	          verified: !external,
368	          verifiedAt: external ? null : new Date(),
369	          verifyToken: external ? randomBytes(24).toString("hex") : null,
370	        },
371	      });
372	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, sub.id, debitCents);
373	    });
374	  } catch (e) {
375	    if (e instanceof InsufficientBalanceError) {
376	      return { error: "Insufficient balance. Top up your wallet first." };
377	    }
378	    throw e;
379	  }
380	
381	  await db.auditLog.create({
382	    data: {
383	      userId: user.id,
384	      action: "emailhosting.order",
385	      detail: `${name} plan=${plan.name}${external ? " (external — DNS verification required)" : ""}`,
386	    },
387	  });
388	  revalidatePath("/dashboard/email");
389	  return { ok: true };
390	}
