394	/**
395	 * Return the DNS records a customer must publish at their registrar for an
396	 * EXTERNAL domain so mail flows through the Nxeon mail server, plus the
397	 * ownership-verification record. Ownership-checked (caller must own the sub).
398	 *
399	 * The DKIM record is fetched from Mailcow (`mcGetDkim`) and cached in
400	 * `dkimRecord`; when Mailcow isn't configured (or has no key yet) a placeholder
401	 * note is returned so the panel still renders.
402	 */
403	export async function getEmailDnsRecords(
404	  subscriptionId: string,
405	): Promise<{
406	  error?: string;
407	  records?: DnsRecord[];
408	  verified?: boolean;
409	  external?: boolean;
410	  cloudflareConnected?: boolean;
411	}> {
412	  const user = await requireUser();
413	
414	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
415	  if (!sub) return { error: "Subscription not found." };
416	  if (sub.userId !== user.id) return { error: "Not your subscription." };
417	
418	  const domain = sub.domainName;
419	
420	  // Resolve the DKIM TXT: prefer the cached value, else fetch + cache from Mailcow.
421	  let dkimTxt = sub.dkimRecord ?? null;
422	  if (!dkimTxt && mailcowConfigured()) {
423	    try {
424	      // Ensure the mail domain exists so Mailcow has generated a DKIM key.
425	      if (!(await mcDomainExists(domain))) {
426	        await mcCreateDomain(domain).catch(() => {});
427	      }
428	      dkimTxt = await mcGetDkim(domain);
429	      if (dkimTxt) {
430	        await db.emailSubscription
431	          .update({ where: { id: sub.id }, data: { dkimRecord: dkimTxt } })
432	          .catch(() => {});
433	      }
434	    } catch (e) {
435	      console.warn(`[mailcow] get dkim ${domain} failed:`, e);
436	    }
437	  }
438	
439	  const records: DnsRecord[] = [
440	    {
441	      type: "TXT",
442	      label: "Ownership verification",
443	      host: `_nxeon-verify.${domain}`,
444	      value: `nxeon-verify=${sub.verifyToken ?? ""}`,
445	      note: "Proves you control this domain. Required before mail is enabled.",
446	    },
447	    {
448	      type: "MX",
449	      label: "Mail routing (MX)",
450	      host: domain,
451	      value: MAIL_HOST,
452	      priority: MAIL_MX_PRIORITY,
453	    },
454	    {
455	      type: "TXT",
456	      label: "SPF",
457	      host: domain,
458	      value: SPF_VALUE,
459	      note: "Authorizes the Nxeon mail server to send for your domain.",
460	    },
461	    {
462	      type: "TXT",
463	      label: "DKIM",
464	      host: `${DKIM_SELECTOR}._domainkey.${domain}`,
465	      value: dkimTxt ?? "",
466	      note: dkimTxt
467	        ? undefined
468	        : "DKIM key is being generated on the mail server — refresh this page shortly to see the value.",
469	    },
470	    {
471	      type: "TXT",
472	      label: "DMARC",
473	      host: `_dmarc.${domain}`,
474	      value: DMARC_VALUE,
475	      note: "Reporting policy for messages that fail SPF/DKIM.",
476	    },
477	  ];
478	
479	  return {
480	    records,
481	    verified: sub.verified,
482	    external: sub.external,
483	    // True for either connection shape (OAuth credentials or a legacy token).
484	    cloudflareConnected: readStoredCloudflare(user.cloudflareTokenEnc) !== null,
485	  };
486	}
