488	/**
489	 * Verify that an EXTERNAL domain's owner has published our verification record.
490	 * Resolves the `_nxeon-verify` TXT via DNS and confirms it contains
491	 * `nxeon-verify=<verifyToken>`; the MX pointing at the mail host is accepted as
492	 * corroboration. The result is derived entirely server-side from live DNS —
493	 * client input never decides the outcome. Rate-limited per user + subscription.
494	 */
495	export async function verifyEmailDomain(subscriptionId: string): Promise<Result> {
496	  const user = await requireUser();
497	
498	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
499	  if (!sub) return { error: "Subscription not found." };
500	  if (sub.userId !== user.id) return { error: "Not your subscription." };
501	  if (!sub.external) return { error: "This domain is managed by Nxeon — no verification needed." };
502	  if (sub.verified) return { ok: true };
503	  if (!sub.verifyToken) return { error: "No verification token on this subscription." };
504	
505	  const rl = checkRateLimit(`email-verify:${user.id}:${sub.id}`, {
506	    max: 6,
507	    windowMs: 60_000,
508	  });
509	  if (!rl.ok) {
510	    return { error: `Too many verification attempts. Try again in ${rl.retryAfterSec}s.` };
511	  }
512	
513	  const domain = sub.domainName;
514	  const expected = `nxeon-verify=${sub.verifyToken}`;
515	
516	  // Primary signal: the verification TXT record must contain our exact token.
517	  let tokenFound = false;
518	  try {
519	    const txt = await resolveTxt(`_nxeon-verify.${domain}`);
520	    // Each record may be split into multiple strings — join per-record chunks.
521	    tokenFound = txt.some((chunks) => chunks.join("").trim() === expected);
522	  } catch {
523	    tokenFound = false;
524	  }
525	
526	  // Corroboration: MX pointing at the mail host (does not substitute for the token).
527	  let mxOk = false;
528	  try {
529	    const mx = await resolveMx(domain);
530	    mxOk = mx.some((r) => r.exchange.replace(/\.$/, "").toLowerCase() === MAIL_HOST);
531	  } catch {
532	    mxOk = false;
533	  }
534	
535	  if (!tokenFound) {
536	    return {
537	      error: mxOk
538	        ? "MX is set, but the _nxeon-verify TXT record isn't visible yet. DNS can take a few minutes to propagate."
539	        : "Verification record not found yet. Add the _nxeon-verify TXT record and try again (DNS can take a few minutes).",
540	    };
541	  }
542	
543	  await db.emailSubscription.update({
544	    where: { id: sub.id },
545	    data: { verified: true, verifiedAt: new Date() },
546	  });
547	
548	  await db.auditLog.create({
549	    data: {
550	      userId: user.id,
551	      action: "emailhosting.verify",
552	      detail: `${domain}${mxOk ? " (MX + TXT)" : " (TXT)"}`,
553	    },
554	  });
555	  revalidatePath("/dashboard/email");
556	  return { ok: true };
557	}
558	
559	// ---------- Deliverability self-check ----------
560	
561	/**
562	 * Run the SPF / DKIM / DMARC / MX self-check for a subscription the caller owns.
563	 *
564	 * WHY: "my mail goes to spam" was previously undiagnosable from inside the
565	 * product — the platform owner hit exactly this and had to reach for an external
566	 * tool. This returns pass/fail per record with the value actually observed beside
567	 * the expected one, so the customer can see which DNS row is wrong.
568	 *
569	 * Two correctness rules this depends on:
570	 *   - DNS is read from the ZONE'S AUTHORITATIVE NAMESERVERS, never the system
571	 *     resolver (see lib/mail/deliverability.ts — this host's `hosts: files …`
572	 *     nsswitch order can answer from /etc/hosts and looks like a real lookup).
573	 *   - DKIM is compared against Mailcow's LIVE key, not `sub.dkimRecord`, which is
574	 *     a write-once cache that can outlive a key rotation.
575	 *
576	 * Rate-limited: each run makes several outbound DNS queries plus one Mailcow call.
577	 */
578	export async function checkEmailDeliverability(
579	  subscriptionId: string,
580	): Promise<{ error?: string; report?: DeliverabilityReport }> {
581	  const user = await requireUser();
582	
583	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
584	  if (!sub) return { error: "Subscription not found." };
585	  if (sub.userId !== user.id) return { error: "Not your subscription." };
586	  // A cancelled subscription's domain may since have been taken by another
587	  // customer (the duplicate guard in orderEmailHosting only excludes CANCELLED
588	  // rows), so the old owner must not keep a live probe pointed at it.
589	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
590	
591	  // NOTE on domain verification: this check deliberately does NOT require
592	  // `sub.verified`, unlike every action that changes mail routing. It only READS
593	  // public DNS and Mailcow's public DKIM key, changes nothing, and an unverified
594	  // domain is precisely the case a customer needs it for — gating it would hide
595	  // the diagnosis exactly when the records are wrong. Ownership of the
596	  // subscription is still required so the panel can't be used to scan arbitrary
597	  // domains through our server.
598	  const rl = checkRateLimit(`email-deliverability:${user.id}`, { max: 10, windowMs: 60_000 });
599	  if (!rl.ok) return { error: `Too many checks. Try again in ${rl.retryAfterSec}s.` };
600	
601	  // LIVE key only. A failure here degrades the DKIM row to "unknown" rather than
602	  // silently comparing against a cached value that may no longer sign anything.
603	  let dkim: { selector: string; txt: string } | null = null;
604	  if (mailcowConfigured()) {
605	    try {
606	      const live = await mcGetDkimDetails(sub.domainName);
607	      if (live) dkim = { selector: live.selector, txt: live.txt };
608	    } catch (e) {
609	      console.warn(`[mailcow] live dkim lookup for ${sub.domainName} failed:`, e);
610	    }
611	  }
612	
613	  try {
614	    const report = await checkDeliverability({
615	      domain: sub.domainName,
616	      mailHost: MAIL_HOST,
617	      spfInclude: SPF_INCLUDE,
618	      spfExpected: SPF_VALUE,
619	      dmarcExpected: DMARC_VALUE,
620	      dkim,
621	    });
622	    return { report };
623	  } catch (e) {
624	    console.warn(`[deliverability] check for ${sub.domainName} failed:`, e);
625	    return { error: "Couldn't complete the DNS check right now. Please try again in a moment." };
626	  }
627	}
628	
629	// Local-part of an email address: RFC-ish, conservative. No leading/trailing dot.
630	const localPartRe = /^[a-z0-9]+(?:[._-][a-z0-9]+)*$/;
631	
632	/**
633	 * Add a mailbox to a subscription the caller owns. Enforces the plan's mailbox
634	 * quota and address uniqueness within the subscription, records the intended
635	 * mailbox (status PROVISIONING), then attempts to provision it on Mailcow. A
636	 * Mailcow failure leaves the row as FAILED (retryable) but never fails the call.
637	 */
638	export async function addMailbox(subscriptionId: string, localPart: string): Promise<Result> {
639	  const user = await requireUser();
640	
641	  const sub = await db.emailSubscription.findUnique({
642	    where: { id: subscriptionId },
643	    include: { emailPlan: true, mailboxes: true },
644	  });
645	  if (!sub) return { error: "Subscription not found." };
646	  if (sub.userId !== user.id) return { error: "Not your subscription." };
647	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
648	  // SECURITY (added 2026-07-25): defence in depth against the cross-tenant
649	  // takeover fixed in subscribeEmail(). Owning the subscription ROW is not proof
650	  // of owning the DOMAIN — and because Mailcow keys mailboxes by address, any
651	  // mailbox minted here acts on that domain's real mail. An external domain must
652	  // prove control via DNS before it can mint a single address, so even if a
653	  // duplicate subscription is ever created again this cannot be weaponised.
654	  if (sub.external && !sub.verified) {
655	    return {
656	      error: "Verify this domain first — add the DNS record shown on this page, then click Verify.",
657	    };
658	  }
659	
660	  const local = String(localPart ?? "").trim().toLowerCase();
661	  if (!localPartRe.test(local) || local.length > 64) {
662	    return { error: "Enter a valid mailbox name (letters, numbers, . _ - )." };
663	  }
664	
665	  const address = `${local}@${sub.domainName}`;
666	
667	  if (sub.mailboxes.length >= sub.emailPlan.mailboxes) {
668	    return {
669	      error: `Plan limit reached (${sub.emailPlan.mailboxes} mailbox${sub.emailPlan.mailboxes === 1 ? "" : "es"}). Upgrade to add more.`,
670	    };
671	  }
672	  if (sub.mailboxes.some((m) => m.address.toLowerCase() === address)) {
673	    return { error: "That address already exists." };
674	  }
675	
676	  // Per-mailbox quota (MB) comes from the plan tier's per-mailbox storage (GB).
677	  const quotaMB = sub.emailPlan.storageGB * 1024;
678	
679	  const mailbox = await db.mailbox.create({
680	    data: { subscriptionId: sub.id, address, quotaMB, status: "PROVISIONING" },
681	  });
682	
683	  await db.auditLog.create({
684	    data: { userId: user.id, action: "mailbox.add", detail: address },
685	  });
686	
687	  // Additive, failure-tolerant provisioning — never throws out of the flow.
688	  await provisionMailboxOnMailcow({
689	    id: mailbox.id,
690	    address: mailbox.address,
691	    quotaMB,
692	    subscription: { domainName: sub.domainName },
693	  });
694	
695	  revalidatePath("/dashboard/email");
696	  return { ok: true };
