746	/** Remove a mailbox the caller owns (via its subscription). */
747	export async function removeMailbox(mailboxId: string): Promise<Result> {
748	  const user = await requireUser();
749	
750	  const mailbox = await db.mailbox.findUnique({
751	    where: { id: mailboxId },
752	    include: { subscription: true },
753	  });
754	  if (!mailbox) return { error: "Mailbox not found." };
755	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
756	
757	  // Delete on Mailcow BEFORE dropping our row — and distinguish the two failure
758	  // modes, because they demand opposite actions:
759	  //
760	  //   - Mailcow REFUSED (reachable, returned an error): the mail server and our
761	  //     database disagree about this mailbox. Deleting our row here would leave a
762	  //     LIVE mailbox still receiving the customer's mail with no record of it in
763	  //     the product — silent data loss. Surface the error and keep the row.
764	  //   - Mailcow UNREACHABLE (transport failure): the server may just be down.
765	  //     Blocking removal forever on an outage is wrong, so we drop our row and
766	  //     tell the customer the mailbox itself may still exist and to retry once
767	  //     mail service is back.
768	  //
769	  // The previous `.catch(() => {})` collapsed both into "deleted, ok:true" — the
770	  // worse answer in every case.
771	  let mailcowUnreachable = false;
772	  if (mailcowConfigured()) {
773	    try {
774	      await mcDeleteMailbox(mailbox.address);
775	    } catch (e) {
776	      if (isMailcowUnreachable(e)) {
777	        mailcowUnreachable = true;
778	        console.warn(`[mailcow] delete ${mailbox.address}: unreachable, removing local record anyway:`, e);
779	      } else {
780	        console.error(`[mailcow] delete ${mailbox.address} REFUSED:`, e);
781	        return {
782	          error:
783	            "The mail server wouldn't remove this mailbox, so we've left it in place rather than lose your mail. Please try again in a moment, or contact support if it keeps happening.",
784	        };
785	      }
786	    }
787	  }
788	
789	  await db.mailbox.delete({ where: { id: mailbox.id } });
790	
791	  await db.auditLog.create({
792	    data: {
793	      userId: user.id,
794	      action: "mailbox.remove",
795	      detail: mailcowUnreachable ? `${mailbox.address} (mailcow unreachable — server-side delete not confirmed)` : mailbox.address,
796	    },
797	  });
798	  revalidatePath("/dashboard/email");
799	  return mailcowUnreachable
800	    ? {
801	        ok: true,
802	        warning:
803	          "Removed from your account. The mail server was unreachable, so the mailbox itself may still exist — it will be cleared when mail service is back, or contact support if messages keep arriving.",
804	      }
805	    : { ok: true };
806	}
