808	/**
809	 * Suspend or resume a mailbox the caller owns, mirroring the state onto Mailcow
810	 * (deactivate/activate). Owner-only, failure-tolerant on the Mailcow call.
811	 */
812	export async function setMailboxSuspended(mailboxId: string, suspended: boolean): Promise<Result> {
813	  const user = await requireUser();
814	
815	  const mailbox = await db.mailbox.findUnique({
816	    where: { id: mailboxId },
817	    include: { subscription: true },
818	  });
819	  if (!mailbox) return { error: "Mailbox not found." };
820	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
821	
822	  // A REFUSAL means the flip did not happen on the mail server, so writing our
823	  // status to SUSPENDED/ACTIVE would be a lie the customer acts on — a "suspended"
824	  // mailbox that keeps sending and receiving, or vice versa. Only an UNREACHABLE
825	  // server is tolerated (the state will reconcile), and even then the customer is
826	  // told the mail server did not confirm.
827	  let mailcowUnreachable = false;
828	  if (mailcowConfigured()) {
829	    try {
830	      await mcSetMailboxActive(mailbox.address, !suspended);
831	    } catch (e) {
832	      if (isMailcowUnreachable(e)) {
833	        mailcowUnreachable = true;
834	        console.warn(`[mailcow] set active ${mailbox.address}: unreachable, updating local status anyway:`, e);
835	      } else {
836	        console.error(`[mailcow] set active ${mailbox.address} REFUSED:`, e);
837	        return {
838	          error: `The mail server wouldn't ${suspended ? "suspend" : "resume"} this mailbox, so nothing was changed. Please try again in a moment.`,
839	        };
840	      }
841	    }
842	  }
843	
844	  await db.mailbox.update({
845	    where: { id: mailbox.id },
846	    data: { status: suspended ? "SUSPENDED" : "ACTIVE" },
847	  });
848	
849	  await db.auditLog.create({
850	    data: {
851	      userId: user.id,
852	      action: suspended ? "mailbox.suspend" : "mailbox.resume",
853	      detail: mailbox.address,
854	    },
855	  });
856	  revalidatePath("/dashboard/email");
857	  return mailcowUnreachable
858	    ? {
859	        ok: true,
860	        warning: `Updated in your account, but the mail server was unreachable so it may not be ${suspended ? "suspended" : "active"} yet — it will reconcile when mail service is back.`,
861	      }
862	    : { ok: true };
863	}
