953	/**
954	 * Store a customer's Cloudflare API token (encrypted) so we can create their
955	 * mail DNS records for them. The token is verified against Cloudflare before it
956	 * is saved, so we never persist a dud. requireUser + rate-limited; the token is
957	 * never logged or returned. Scope guidance (Zone → DNS → Edit) lives in the UI.
958	 */
959	export async function saveCloudflareToken(token: string): Promise<Result> {
960	  const user = await requireUser();
961	
962	  const t = String(token ?? "").trim();
963	  if (!t) return { error: "Paste your Cloudflare API token." };
964	  if (t.length < 20 || t.length > 200) {
965	    return { error: "That doesn't look like a Cloudflare API token." };
966	  }
967	
968	  const rl = checkRateLimit(`cf-token:${user.id}`, { max: 6, windowMs: 60_000 });
969	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
970	
971	  let valid = false;
972	  try {
973	    valid = await cfVerifyToken(t);
974	  } catch (e) {
975	    console.warn("[cloudflare] token verify failed:", e);
976	    return { error: "Couldn't reach Cloudflare to verify the token. Try again shortly." };
977	  }
978	  if (!valid) {
979	    return {
980	      error: "Cloudflare rejected that token. Check it's active and scoped to Zone → DNS → Edit.",
981	    };
982	  }
983	
984	  await db.user.update({
985	    where: { id: user.id },
986	    data: { cloudflareTokenEnc: encryptSecret(t) },
987	  });
988	  await db.auditLog.create({
989	    data: { userId: user.id, action: "cloudflare.connect", detail: "API token saved" },
990	  });
991	  revalidatePath("/dashboard/email");
992	  return { ok: true };
