995	/**
996	 * Auto-create the mail DNS records for an EXTERNAL email subscription in the
997	 * customer's Cloudflare zone, using their stored token. Ownership-checked and
998	 * rate-limited. Reuses getEmailDnsRecords as the single source of truth for the
999	 * record set (ownership verify TXT, MX, SPF, DKIM, DMARC), upserts each into the
1000	 * zone, then leaves the existing verifyEmailDomain flow to confirm. Fails
1001	 * gracefully with clear messages for invalid token / zone-not-found.
1002	 */
1003	export async function autoCreateEmailDns(
1004	  subscriptionId: string,
1005	): Promise<{ error?: string; ok?: boolean; created?: string[] }> {
1006	  const user = await requireUser();
1007	
1008	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
1009	  if (!sub) return { error: "Subscription not found." };
1010	  if (sub.userId !== user.id) return { error: "Not your subscription." };
1011	  if (!sub.external) {
1012	    return { error: "This domain is managed by Nxeon — no external DNS setup is needed." };
1013	  }
1014	
1015	  const rl = checkRateLimit(`cf-autodns:${user.id}:${sub.id}`, { max: 4, windowMs: 60_000 });
1016	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
1017	
1018	  // Works for both connection shapes: OAuth credentials (refreshed here when
1019	  // stale) and a legacy pasted API token. Never handles the plaintext itself.
1020	  const resolved = await resolveCloudflareToken(user);
1021	  const token = resolved.token;
1022	  if (!token) return { error: resolved.error ?? "Connect Cloudflare first." };
1023	
1024	  // Same record set the customer would otherwise publish by hand.
1025	  const dns = await getEmailDnsRecords(subscriptionId);
1026	  if (dns.error) return { error: dns.error };
1027	  const records = (dns.records ?? []).filter((r) => r.type === "MX" || r.value.trim());
1028	  if (records.length === 0) {
1029	    return { error: "No DNS records to create yet — try again in a moment." };
1030	  }
1031	
1032	  // SANDBOX: never contact Cloudflare — report what we would have published so
1033	  // staging can walk the whole "connect → records added" flow.
1034	  if (SANDBOX) {
1035	    return {
1036	      ok: true,
1037	      created: records.map((r) => `${r.label} (${r.type}, created)`),
1038	    };
1039	  }
1040	
1041	  let zoneId: string | null;
1042	  try {
1043	    zoneId = await cfFindZoneId(token, sub.domainName);
1044	  } catch (e) {
1045	    if (e instanceof CloudflareError) {
1046	      return { error: `Cloudflare error: ${e.message}` };
1047	    }
1048	    throw e;
1049	  }
1050	  if (!zoneId) {
1051	    return {
1052	      error: `No Cloudflare zone found for ${sub.domainName}. Add the domain to Cloudflare first, or check the token is scoped to this zone.`,
1053	    };
1054	  }
1055	
1056	  let created: string[];
1057	  try {
1058	    const results = await cfUpsertRecords(
1059	      token,
1060	      zoneId,
1061	      records.map((r) => ({
1062	        type: r.type,
1063	        name: r.host,
1064	        content: r.value,
1065	        priority: r.priority,
1066	      })),
1067	    );
1068	    created = results.map((res) => {
1069	      const label = records.find((r) => r.host === res.name && r.type === res.type)?.label ?? res.name;
1070	      return `${label} (${res.type}, ${res.action})`;
1071	    });
1072	  } catch (e) {
1073	    if (e instanceof CloudflareError) {
1074	      return {
1075	        error: `Couldn't create records in Cloudflare: ${e.message}. Check the token has Zone → DNS → Edit permission.`,
1076	      };
1077	    }
1078	    throw e;
1079	  }
1080	
1081	  await db.auditLog.create({
1082	    data: {
1083	      userId: user.id,
1084	      action: "cloudflare.autodns",
1085	      detail: `${sub.domainName} — ${created.length} record(s)`,
1086	    },
1087	  });
1088	  revalidatePath("/dashboard/email");
1089	  return { ok: true, created };
1090	}
