88	/**
89	 * Turn a desired label into a globally-unique, valid subdomain slug. Tries the
90	 * sanitized base, then `-2`, `-3`, …, and finally a random suffix. Uniqueness is
91	 * ultimately enforced by the DB `@@unique([slug])`; this just avoids the common
92	 * collisions before the insert.
93	 */
94	async function uniqueSlug(base: string): Promise<string> {
95	  let root = sanitizeSlug(base);
96	  if (!isValidSlug(root)) root = "site";
97	  // Reserve room for a numeric suffix within the 63-char label limit.
98	  if (root.length > 50) root = root.slice(0, 50).replace(/-+$/g, "");
99	  for (let i = 1; i <= 25; i++) {
100	    const candidate = i === 1 ? root : `${root}-${i}`;
101	    const taken = await db.site.findUnique({ where: { slug: candidate }, select: { id: true } });
102	    if (!taken) return candidate;
103	  }
104	  // Fallback: a random suffix makes a collision astronomically unlikely.
105	  return `${root}-${Math.random().toString(36).slice(2, 8)}`;
106	}
