254	export async function publishSite(id: string): Promise<Result> {
255	  try {
256	    const { user, site } = await ownedSite(id);
257	    const limited = throttle(user.id, "publish", 12);
258	    if (limited) return { ok: false, error: limited };
259	    if (site.status === "PUBLISHING") {
260	      return { ok: false, error: "This site is already publishing — give it a moment." };
261	    }
262	    const draft = await db.siteVersion.findFirst({
263	      where: { siteId: site.id, isDraft: true },
264	      orderBy: { createdAt: "desc" },
265	    });
266	    if (!draft || !isSiteDocument(draft.document)) {
267	      return { ok: false, error: "There is nothing to publish yet — save your site first." };
268	    }
269	    await db.site.update({ where: { id: site.id }, data: { status: "PUBLISHING", error: null } });
270	    await db.job.create({ data: { type: "SITE_PUBLISH", payload: { siteId: site.id } } });
271	    await db.auditLog.create({
272	      data: { userId: user.id, action: "site.publish", detail: `${site.name} (${site.slug})` },
273	    });
274	    revalidatePath("/dashboard/sites");
275	    return { ok: true };
276	  } catch (err) {
277	    return { ok: false, error: safeError(err) };
278	  }
