26	/** Job types that must not overlap with panel work (lifecycle / destructive). */
27	const EXCLUSIVE_JOBS = [
28	  "PROVISION",
29	  "REINSTALL",
30	  "DELETE",
31	  "RESIZE",
32	  "SUSPEND",
33	  "UNSUSPEND",
34	  "SNAPSHOT_ROLLBACK",
35	  "BACKUP_RESTORE",
36	  // A disk expansion runs growpart/resize2fs over SSH inside the guest; keep the
37	  // control-panel operations out of the way while the root filesystem is resized.
38	  "DISK_EXPAND",
