41	async function ownedServer(serverId: string) {
42	  const user = await requireUser();
43	  const server = await db.server.findUnique({
44	    where: { id: serverId },
45	    select: { id: true, userId: true, status: true, hostname: true },
46	  });
47	  if (!server) throw new Error("Not found");
48	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
49	  return { user, server };
50	}
