52	async function ownedWebsite(id: string) {
53	  const user = await requireUser();
54	  const site = await db.website.findUnique({
55	    where: { id },
56	    include: { server: { select: { id: true, userId: true, status: true } } },
57	  });
58	  if (!site) throw new Error("Not found");
59	  if (site.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
60	  return { user, site };
61	}
