63	function throttle(userId: string, op: string, max: number): string | null {
64	  const rl = checkRateLimit(`cpanel:web:${op}:${userId}`, { max, windowMs: 60_000 });
65	  return rl.ok ? null : `Too many requests — retry in ${rl.retryAfterSec}s.`;
66	}
